// Builds docs/Demand_Copilot_report.docx from reports/report_numbers.json and the figures in docs/assets and reports/figures.
const fs = require("fs");
const path = require("path");
const D = require("docx");
const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, LevelFormat, Table, TableRow, TableCell, WidthType, ShadingType,
        BorderStyle, ImageRun, Footer, PageNumber, PageBreak, VerticalAlign } = D;

const ROOT = path.resolve(__dirname, "..", "..");
const NUM = JSON.parse(fs.readFileSync(path.join(ROOT, "reports", "report_numbers.json"), "utf8"));
const W = NUM.wape, I = NUM.inventory;
const OUT = path.join(ROOT, "docs", "Demand_Copilot_report.docx");
const INK = "0F2A3D", TEAL = "1F8A8A", SLATE = "5B6B75", GRID = "D5DCE0", LIGHT = "F1F5F6", BRICK = "B8483A";
const TW = 9638; // content width in DXA (A4, 2 cm margins)

const f2 = (v, d = 4) => v.toFixed(d).replace(".", ",");
const sg = (v) => `${v >= 0 ? "+" : "−"}${Math.abs(v * 100).toFixed(1).replace(".", ",")}%`;
const pct = (a, b) => `${a / b - 1 >= 0 ? "+" : "−"}${Math.abs((a / b - 1) * 100).toFixed(1).replace(".", ",")}%`;

const run = (t, o = {}) => new TextRun({ text: t, ...o });
const p = (children, o = {}) => new Paragraph({ spacing: { after: 120, line: 276 }, ...o, children: typeof children === "string" ? [run(children)] : children });
const rich = (parts, o = {}) => p(parts.map((x) => (typeof x === "string" ? run(x) : run(x.t, x))), o);
const h1 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [run(t)] });
const h2 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_2, children: [run(t)] });
const bullet = (parts) => new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 80, line: 276 },
  children: (Array.isArray(parts) ? parts : [parts]).map((x) => (typeof x === "string" ? run(x) : run(x.t, x))) });
const step = (parts) => new Paragraph({ numbering: { reference: "steps", level: 0 }, spacing: { after: 80, line: 276 },
  children: (Array.isArray(parts) ? parts : [parts]).map((x) => (typeof x === "string" ? run(x) : run(x.t, x))) });
const caption = (t) => new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 60, after: 200 }, children: [run(t, { italics: true, size: 18, color: SLATE })] });
const img = (file, wIn, hIn, alt) => new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 120, after: 0 },
  children: [new ImageRun({ type: path.extname(file).slice(1).replace("jpg", "jpg"), data: fs.readFileSync(file), transformation: { width: Math.round(wIn * 96), height: Math.round(hIn * 96) },
    altText: { title: alt, description: alt, name: alt } })] });

const border = { style: BorderStyle.SINGLE, size: 4, color: GRID };
const borders = { top: border, bottom: border, left: border, right: border };
function table(header, rows, widths, opts = {}) {
  const cell = (t, w, o = {}) => new TableCell({ width: { size: w, type: WidthType.DXA }, borders, verticalAlign: VerticalAlign.CENTER,
    shading: o.fill ? { fill: o.fill, type: ShadingType.CLEAR, color: "auto" } : undefined, margins: { top: 60, bottom: 60, left: 100, right: 100 },
    children: [new Paragraph({ alignment: o.align || AlignmentType.LEFT, children: [run(String(t), { size: 20, bold: !!o.bold, color: o.color })] })] });
  const align = opts.align || header.map(() => AlignmentType.LEFT);
  return new Table({ width: { size: widths.reduce((a, b) => a + b, 0), type: WidthType.DXA }, columnWidths: widths, rows: [
    new TableRow({ tableHeader: true, cantSplit: true, children: header.map((h, i) => cell(h, widths[i], { fill: INK, bold: true, color: "FFFFFF", align: align[i] })) }),
    ...rows.map((r, ri) => new TableRow({ cantSplit: true, children: r.map((c, i) => {
      const o = typeof c === "object" ? c : { t: c };
      return cell(o.t, widths[i], { align: align[i], bold: o.bold || (opts.boldRow === ri), fill: o.fill || (opts.hl === ri ? "E3F1F1" : undefined), color: o.color });
    }) })),
  ] });
}
const spacer = () => new Paragraph({ spacing: { after: 160 }, children: [] });
const fig = (name) => path.join(ROOT, "docs", "assets", name);
const rfig = (name) => path.join(ROOT, "reports", "figures", name);

const R = AlignmentType.RIGHT;
const body = [];
const add = (...x) => body.push(...x);

// Title page
add(new Paragraph({ spacing: { before: 2400, after: 200 }, children: [run("Demand Copilot", { font: "Cambria", size: 64, bold: true, color: INK })] }),
  new Paragraph({ spacing: { after: 400 }, children: [run("Прогноз спроса и план закупок для малого магазина", { font: "Cambria", size: 34, color: TEAL })] }),
  p([run("Технический отчёт к финальному проекту", { size: 26 })]),
  p([run("Дисциплина: AI Essentials: Theory and Applications", { size: 26 })]),
  new Paragraph({ spacing: { before: 600, after: 80 }, children: [run("Авторы", { bold: true, size: 24 })] }),
  p("[Имя Фамилия], [Имя Фамилия], [Имя Фамилия]"),
  p([run("Репозиторий: ", { bold: true }), run("demand_copilot (локальный git; ссылку на удалённый репозиторий добавить, когда он будет создан)")]),
  p([run("Версия отчёта: ноябрь 2026. Числа в отчёте взяты из файлов в каталоге reports/ репозитория.", { color: SLATE, size: 20 })]),
  new Paragraph({ children: [new PageBreak()] }));

// 1
add(h1("1. Постановка задачи и актуальность"));
add(p("Малый магазин обычно закупает товар «на глаз», по таблице в Excel или по правилу «взять столько, сколько продалось на прошлой неделе». Такое правило не различает товары с устойчивым и редким спросом, не учитывает рисунок по дням недели и запаздывает при изменении уровня продаж. Результат — либо пустая полка, либо замороженные в запасах деньги."));
add(rich([{ t: "Пользователь: ", bold: true }, "владелец или закупщик небольшого магазина."]));
add(rich([{ t: "Задача: ", bold: true }, "по истории продаж каждого товара предсказать спрос на 28 дней вперёд и на этой основе предложить недельный план закупок: что и сколько заказать при заданном сроке поставки и целевом уровне обслуживания."]));
add(rich([{ t: "Критерии успеха, заданные заранее:", bold: true }]));
add(bullet("прогноз точнее seasonal naive (значение недельной давности) минимум на 10–15% по WAPE;"),
  bullet("при том же уровне обслуживания нужно меньше запаса, чем по правилу «как на прошлой неделе» и по простым средним;"),
  bullet("проверка на окне, которое не использовалось ни для обучения, ни для настройки, ни для выбора признаков."));
add(rich([{ t: "Почему ML. ", bold: true }, "Простое правило использует один показатель (продано на прошлой неделе). Модель на всех товарах сразу учитывает несколько окон недавнего уровня продаж, долю дней без продаж, давность последней продажи и шаг горизонта. Выгоду нельзя заявлять заранее, её измеряют сравнением с простыми методами (раздел 4); к чему это привело, описано ниже."]));

// 2
add(h1("2. Данные и их подготовка"));
add(h2("2.1. Источник и состав"));
add(p("Используется открытый набор M5 (продажи сети Walmart) в виде зеркала на GitHub, его можно скачать без регистрации. Из него взяты файлы продаж по дням, цен и календаря. Данные содержат 3 049 товаров в 10 магазинах за период с 29.01.2011 по 19.06.2016 (1 969 дней)."));
add(p("В данных нет остатков на складе, закупочных цен и сроков поставки. Поэтому качество прогноза проверяется на реальных продажах, а качество закупок — в симуляции склада с явно заданными допущениями. Это главное ограничение проекта."));
add(h2("2.2. Подвыборка"));
add(p("Взят один магазин (CA_1, 3 049 товаров, из них 3 012 подходят: у них есть история не менее года и продажи за последний год). Из подходящих выбраны 300 товаров: по 100 из трёх групп по объёму продаж за последний год (низкий, средний, высокий). Отбор использовал данные только до 1829-го дня, поэтому не видит окон оценки. Итоговая таблица содержит 590 700 строк (300 товаров × 1 969 дней)."));
add(p("По классификации Syntetos–Boylan (средний интервал между продажами и вариативность размеров) товары распределились так: прерывистые — 225, «комковатые» — 46, гладкие — 20, нерегулярные — 9. То есть спрос в основном разреженный."));
add(h2("2.3. Разведочный анализ"));
add(bullet("54% дней, когда товар был в продаже, дали нулевые продажи (у товаров низкого объёма 77%, высокого 33%)."),
  bullet("Рисунок по дням недели сильный: в субботу и воскресенье продаётся примерно на 50% больше, чем со вторника по четверг."),
  bullet("В дни выплат пособий (SNAP) продажи выше на 8,8%; в Рождество магазин закрыт (нулевые продажи по всем товарам)."),
  bullet("Магазин растёт: суммарные продажи выросли примерно с 9–10 тыс. до 15–16 тыс. единиц в месяц."));
add(img(rfig("eda_overview.png"), 6.2, 3.8, "Обзор данных: ежедневные продажи, рисунок по дням недели, месячный тренд, интервал между продажами"));
add(caption("Рис. 1. Разведочный анализ подвыборки (300 товаров магазина CA_1)"));
add(h2("2.4. Разбиение и защита от утечек"));
add(p("Разбиение только по времени. Окно — это 28 дней прогноза после даты отсечения; модель обучается на днях до даты отсечения."));
add(table(["Назначение", "Дата отсечения", "Окно прогноза", "Что делалось"],
  [["dev (3 окна)", "d1829, d1857, d1885", "по 28 дней после даты", "подбор параметров и отбор признаков"],
   ["validation", "d1913", "d1914–d1941", "проверка после выбора"],
   ["тест", "d1941", "d1942–d1969 (23.05–19.06.2016)", "оценён один раз, в самом конце"]], [1900, 2300, 2900, 2538]));
add(spacer());
add(p("Меры против утечки: признаки спроса считаются только по дням до даты прогноза (все скользящие статистики сдвинуты); цены и календарь будущих дней можно считать известными заранее и используются только в проверочных экспериментах; подвыборка товаров выбрана по данным до первого окна; тест оценивается скриптом, который сверяет хеш модели и отказывается запускаться повторно. Прогноз обнуляется для дней, когда у товара нет цены (товар не продаётся) — одинаково для всех методов."));
add(p("Товары без продаж за 28 дней до даты отсечения («спящие») исключены из симуляции закупок: если спрос возобновляется после долгой паузы, его не может предсказать ни один метод, а данные не отличают отсутствие товара от снятия с продажи. На разных окнах это 3–4% стоимости спроса."));

// 3
add(h1("3. Методы"));
add(h2("3.1. Базовые методы"));
add(p("Лестница от простого к сложному, все методы оцениваются на одинаковых окнах:"));
add(bullet("naive (последнее значение) и seasonal naive (значение недельной давности);"),
  bullet("скользящее среднее за 28 дней и среднее по дням недели за 8 недель;"),
  bullet("ETS (AutoETS) и методы для прерывистого спроса Croston-SBA и TSB;"),
  bullet("эмпирические квантили по дням недели (для сравнения квантильных прогнозов; в итоговую модель квантили не вошли)."));
add(h2("3.2. Основная модель"));
add(p("Одна общая модель LightGBM (градиентный бустинг по деревьям) для всех товаров с функцией потерь Tweedie, которая подходит для неотрицательных счётных данных с большим числом нулей. Модель прямая и многошаговая: для каждого товара, даты прогноза и шага горизонта h (1…28) строится строка признаков и предсказывается спрос в день h."));
add(p("Обучающая выборка — около 1,17 млн строк: даты прогноза идут с шагом 7 дней, 150 дат до (дата отсечения − 28), чтобы метки не выходили за дату отсечения. Параметры: 400 деревьев, скорость обучения 0,05, 63 листа, минимум 50 объектов в листе, доли строк и признаков 0,8, степень Tweedie 1,1."));
add(rich([{ t: "Признаки итоговой модели (11): ", bold: true }, "средние продажи за 7, 14, 28, 56 и 91 день, стандартное отклонение за 28 дней, доля дней с продажами за 28 и 91 день, число дней с последней продажи, возраст товара и шаг горизонта h. День недели целевого дня выражается через h, потому что все даты прогноза приходятся на воскресенье."]));
add(p("Всего в проекте проверялись 24 признака: к этим одиннадцати добавлялись цена и её отношение к медиане, SNAP, события, месяц и день месяца, день недели, средние по дню недели и тип товара. Выбор набора описан в разделе 4."));
add(h2("3.3. Слой закупок и симуляция склада"));
add(p("Политика с периодическим пересмотром и уровнем «до которого дозаказываем»: раз в 7 дней рассчитывается целевой уровень S = прогноз спроса на срок поставки и неделю + z·σ, где σ — стандартное отклонение продаж за последние 91 день, умноженное на корень из длины периода. Заказ = S − остаток − уже заказанное, поставка приходит через L дней (1, 3 или 7). Коэффициент z подбирается под нужный уровень обслуживания."));
add(p("Допущения симуляции (заданы нами, в данных их нет): непроданное при нехватке теряется, единицы целые, начальный запас равен спросу за L дней по среднему за 28 дней, спрос равен наблюдаемым продажам. Прогнозы в симуляции обновляются каждую неделю по уже наблюдённым продажам (модель при этом не переобучается). Уровень обслуживания — доля выручки, обслуженная из наличия; запас измеряется в днях продаж, поэтому неизвестная закупочная цена в результат не входит и прибыль не оценивалась."));

