add(img(fig("fig_inventory_by_split.png"), 6.0, 2.55, "Запас в днях продаж по политикам"));
add(caption("Рис. 4. Запас для 95% обслуживания, срок поставки 3 дня"));
const b = NUM.lean_vs_earlier_bootstrap;
